#include "../src/game/level1_scene_objects.hpp"
#include "../src/game/level1_minigames.hpp"
struct Context:shin::game::ObjectResponseContext {int g=0;shin::Level1Minigames games;int&global(unsigned)override{return g;}int sound(unsigned)override{throw std::runtime_error("sound");}int call(unsigned id,shin::PlayerPayload&,shin::game::EntityPayload&,std::initializer_list<std::int64_t>)override{if(id==0x401d10||id==0x41ba30){games.start(id==0x401d10?0x7b:0x7c);return 0;}throw std::runtime_error("call");}};
int main(int argc,char**argv){if(argc!=2)return 1;shin::AssetStore assets(argv[1]);assets.image("gamecar.app");assets.image("gamech_b.app");shin::Level1SceneObjects system;system.spawn(0x41,100,100);shin::PlayerPayload player;player.at(8)=105;player.at(12)=100;player.at(0x34)=10;player.at(0x38)=10;shin::IndexedSurface frame(640,480);Context ctx;int count=0;auto event=[&](unsigned a,unsigned b,unsigned c,unsigned d){if(a!=0x443cd0||b!=0x443e30||c!=0x444170||d!=6)throw std::runtime_error("event args");++count;};system.tick(0,0,assets,frame,player,ctx,event);if(count)return 2;system.tick(0,0,assets,frame,player,ctx,event);if(count!=1||system.objects[0].e.state!=2)return 3;system.tick(0,0,assets,frame,player,ctx,event);if(count!=1||!system.objects[0].removed)return 4;for(int type:{0x7b,0x7c}){shin::Level1SceneObjects icons;icons.spawn(type,100,100);icons.tick(0,0,assets,frame,player,ctx,event);icons.tick(0,0,assets,frame,player,ctx,event);if(!ctx.games.active()||ctx.games.type()!=type||icons.objects[0].e.state!=2)return 5;for(unsigned now=1;now<300000&&ctx.games.active();now+=500)ctx.games.tick(now,{},assets,frame);if(ctx.games.active())return 6;}}
